import React, { useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import Icon from 'components/AppIcon';
import api from '../lib/api';

const ResetPasswordPage = () => {
  const [searchParams] = useSearchParams();
  const token = searchParams.get('token') || '';
  const navigate = useNavigate();
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!token) {
      setError('Missing reset token. Use the link from your email or request a new one.');
      return;
    }
    if (password.length < 8) {
      setError('Password must be at least 8 characters');
      return;
    }
    if (password !== confirm) {
      setError('Passwords do not match');
      return;
    }

    setLoading(true);
    try {
      const result = await api.resetPassword({ token, password });
      setSuccess(result.message || 'Password updated.');
      setTimeout(() => navigate('/login', { replace: true }), 2000);
    } catch (err) {
      setError(err.message || 'Could not reset password');
    } finally {
      setLoading(false);
    }
  };

  if (!token) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background p-4">
        <div className="bg-surface p-8 rounded-lg shadow-warm-lg w-full max-w-md text-center">
          <Icon name="AlertCircle" size={40} className="mx-auto text-warning mb-4" />
          <h1 className="text-xl font-heading font-bold mb-2">Invalid reset link</h1>
          <p className="text-text-secondary text-sm mb-6">
            This link is missing or expired. Request a new reset from the sign-in page.
          </p>
          <Link to="/login" className="btn btn-primary px-6 py-2 inline-block">
            Back to sign in
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <div className="bg-surface p-8 rounded-lg shadow-warm-lg w-full max-w-md">
        <div className="text-center mb-6">
          <div className="w-12 h-12 bg-gradient-to-br from-primary to-secondary rounded-lg flex items-center justify-center mx-auto mb-4">
            <Icon name="KeyRound" size={24} color="white" strokeWidth={2.5} />
          </div>
          <h1 className="text-2xl font-heading font-bold text-text-primary">Set new password</h1>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-text-primary mb-1">New password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
              minLength={8}
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-text-primary mb-1">Confirm password</label>
            <input
              type="password"
              value={confirm}
              onChange={(e) => setConfirm(e.target.value)}
              className="w-full px-4 py-3 border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
              minLength={8}
              required
            />
          </div>

          {error && (
            <div className="p-3 rounded-lg bg-error-50 text-error-700 text-sm border border-error-200">
              {error}
            </div>
          )}
          {success && (
            <div className="p-3 rounded-lg bg-success-50 text-success-700 text-sm border border-success-200">
              {success}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full btn btn-primary py-3 disabled:opacity-50"
          >
            {loading ? 'Updating...' : 'Update password'}
          </button>
        </form>

        <p className="text-center text-sm text-text-secondary mt-6">
          <Link to="/login" className="text-primary hover:underline">Back to sign in</Link>
        </p>
      </div>
    </div>
  );
};

export default ResetPasswordPage;
